import{_ as s,o as i,c as t,a2 as e}from"./chunks/framework.BHRgmlt_.js";const k=JSON.parse('{"title":"部署指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment.md","filePath":"guide/deployment.md","lastUpdated":1786252708000}'),n={name:"guide/deployment.md"};function l(h,a,d,p,o,c){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="部署指南" tabindex="-1">部署指南 <a class="header-anchor" href="#部署指南" aria-label="Permalink to &quot;部署指南&quot;">​</a></h1><h2 id="目标架构" tabindex="-1">目标架构 <a class="header-anchor" href="#目标架构" aria-label="Permalink to &quot;目标架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>局域网 (192.168.3.0/24, 网关 192.168.3.1)</span></span>
<span class="line"><span>  ├── NAS 宿主 (192.168.3.6)          eth0 板载 10GbE</span></span>
<span class="line"><span>  │     └── eth1 (USB 网卡 RTL8156)   macvlan parent</span></span>
<span class="line"><span>  │           └── yacd-mihomo 容器 (192.168.3.100)</span></span>
<span class="line"><span>  │                 ├── :80   yacd 面板(Express)</span></span>
<span class="line"><span>  │                 ├── :7890 mihomo mixed-port</span></span>
<span class="line"><span>  │                 ├── :9090 mihomo REST API</span></span>
<span class="line"><span>  │                 └── TUN   透明代理</span></span>
<span class="line"><span>  └── 局域网设备 → 网关/DNS 指向 192.168.3.100</span></span></code></pre></div><h2 id="为什么用-usb-网卡做-macvlan-parent" tabindex="-1">为什么用 USB 网卡做 macvlan parent <a class="header-anchor" href="#为什么用-usb-网卡做-macvlan-parent" aria-label="Permalink to &quot;为什么用 USB 网卡做 macvlan parent&quot;">​</a></h2><p>Docker 的 macvlan 网络有一个内核级限制:</p><blockquote><p><strong>macvlan 父接口不能与其子接口(macvlan 容器)直接通信。</strong></p></blockquote><p>如果容器 macvlan 挂在宿主主网卡 <code>eth0</code> 上,宿主机访问容器会被内核丢弃(同端口隔离)。</p><p><strong>解法</strong>:利用 NAS 的第二个物理网口(USB 网卡 <code>eth1</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>容器 macvlan 挂 eth1 → 宿主从 eth0 跨端口访问 → 经交换机 L2 转发 → 不触发隔离</span></span></code></pre></div><p>这样宿主机 + 局域网设备都能访问容器。完整原理与踩坑见 <a href="./../guide/architecture.html">网络原理</a>与经验文档。</p><h2 id="硬件要求" tabindex="-1">硬件要求 <a class="header-anchor" href="#硬件要求" aria-label="Permalink to &quot;硬件要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>NAS</td><td>有 Docker 的 NAS(如 UGreen DXP 系列 / 群晖 / PVE)</td></tr><tr><td>第二网口</td><td>建议 USB 网卡(RTL8156 2.5G 最佳),作为 macvlan parent</td></tr><tr><td>系统</td><td>Debian 系(base)或任何支持 Docker 的发行版</td></tr></tbody></table><h2 id="部署步骤" tabindex="-1">部署步骤 <a class="header-anchor" href="#部署步骤" aria-label="Permalink to &quot;部署步骤&quot;">​</a></h2><h3 id="_1-安装-yacd-cli" tabindex="-1">1. 安装 yacd CLI <a class="header-anchor" href="#_1-安装-yacd-cli" aria-label="Permalink to &quot;1. 安装 yacd CLI&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/cy745/yacd/master/deploy/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><h3 id="_2-配置-env" tabindex="-1">2. 配置 <code>.env</code> <a class="header-anchor" href="#_2-配置-env" aria-label="Permalink to &quot;2. 配置 \`.env\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.yacd/deploy/.env</span></span></code></pre></div><p>关键项:</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>PARENT_IFACE</code></td><td><code>eth1</code></td><td>macvlan 父网卡(必须是有线/USB 网卡)</td></tr><tr><td><code>SUBNET</code></td><td><code>192.168.3.0/24</code></td><td>局域网网段</td></tr><tr><td><code>GATEWAY</code></td><td><code>192.168.3.1</code></td><td>主路由网关</td></tr><tr><td><code>MIHOMO_IP</code></td><td><code>192.168.3.100</code></td><td>容器固定 IP(旁路由网关/DNS)</td></tr></tbody></table><h3 id="_3-启动" tabindex="-1">3. 启动 <a class="header-anchor" href="#_3-启动" aria-label="Permalink to &quot;3. 启动&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><h3 id="_4-验证" tabindex="-1">4. 验证 <a class="header-anchor" href="#_4-验证" aria-label="Permalink to &quot;4. 验证&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.3.100/api/status</span></span></code></pre></div><h3 id="_5-接入局域网设备" tabindex="-1">5. 接入局域网设备 <a class="header-anchor" href="#_5-接入局域网设备" aria-label="Permalink to &quot;5. 接入局域网设备&quot;">​</a></h3><ul><li><strong>全屋透明代理</strong>:把设备网关 + DNS 设为 <code>192.168.3.100</code></li><li><strong>按设备手动代理</strong>:HTTP/SOCKS 代理 <code>192.168.3.100:7890</code>(需配置 <code>bind-address: 0.0.0.0</code>)</li></ul><h2 id="宿主机上其他容器走代理" tabindex="-1">宿主机上其他容器走代理 <a class="header-anchor" href="#宿主机上其他容器走代理" aria-label="Permalink to &quot;宿主机上其他容器走代理&quot;">​</a></h2><p>目标容器加入同一 macvlan 网络,把默认网关指向 mihomo 容器:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macnet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.3.101</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cap-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NET_ADMIN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">镜</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">像</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ip route replace default via 192.168.3.100; exec &lt;原命令&gt;&quot;</span></span></code></pre></div><p>或通过 <code>HTTP_PROXY=http://192.168.3.100:7890</code> 环境变量(仅对读取代理环境变量的程序生效)。</p><h2 id="更新与升级" tabindex="-1">更新与升级 <a class="header-anchor" href="#更新与升级" aria-label="Permalink to &quot;更新与升级&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 更新到最新版 + 重建容器(配置保留)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> self-update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 仅更新部署脚本,不重建容器</span></span></code></pre></div><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 需二次确认,会清空配置</span></span></code></pre></div>`,33)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
